def test_sync_translator_supports_context_manager():
    with SyncTranslator() as instance:
        assert isinstance(instance, SyncTranslator)

def test_sync_translate_rejects_invalid_destination(sync_translator):
    with pytest.raises(ValueError, match="invalid destination language"):
        sync_translator.translate("Hello", dest="not-a-language")

def test_sync_translate_rejects_invalid_source(sync_translator):
    with pytest.raises(ValueError, match="invalid source language"):
        sync_translator.translate("Hello", src="not-a-language")

def test_translator_rejects_invalid_transport():
    with pytest.raises(ValueError, match="Invalid transport"):
        Translator(transport="invalid_transport")

def test_sync_translator_rejects_invalid_transport():
    with pytest.raises(ValueError, match="Invalid transport"):
        SyncTranslator(transport="invalid_transport")

def test_sync_detect_french(sync_translator):
    result = call_sync_with_retry(
        lambda: sync_translator.detect("Bonjour tout le monde")
    )
    assert result.lang == "fr"
    assert 0.0 <= result.confidence <= 1.0

def test_run_records_have_required_fields():
    data = json.loads(HISTORY_PATH.read_text(encoding="utf-8"))
    required_keys = {"id", "workflow", "status", "conclusion", "created_at"}
    for run in data["runs"]:
        missing = required_keys - set(run.keys())
        assert not missing, f"Run {run.get('id')} missing keys: {missing}"

def test_exactly_one_target_distribution_installed(target_distributions):
    assert len(target_distributions) == 1, (
        "both 'googletrans' and 'googletrans-curl' are installed; tests would be "
        "ambiguous about which module gets imported (a stale copy of the other "
        "name shadows the real target)."
    )

def test_distribution_version_within_supported_range(target_version):
    assert target_version >= MINIMUM_SUPPORTED, (
        f"installed target version {target_version} is older than "
        f"{MINIMUM_SUPPORTED}; the test suite does not describe it"
    )

def test_version_matches_expected_version(target_version, expected_version):
    if expected_version is None:
        pytest.skip("pass --expected-version X.Y.Z to enforce a specific version")
    assert target_version == expected_version

def test_curl_opt_exported_in_4_1_1(target_version):
    if target_version >= Version("4.1.1"):
        assert "CurlOpt" in googletrans.__all__
        assert hasattr(googletrans, "CurlOpt")
